#!/usr/bin/env bash
# Test predictions, noTTA, checkpoint_final (= nnunet_post_train.sh primary settings), then shared evaluator. Descriptive only.
export OMP_NUM_THREADS=1 MKL_NUM_THREADS=1 OPENBLAS_NUM_THREADS=1 nnUNet_raw=${WORKSPACE:-.}/3D_OrganoidSeg/baselines_fair_20261030/nnunet/nnUNet_raw nnUNet_preprocessed=/dev/shm/${USER}_nnUNet_preprocessed nnUNet_compile=f
one(){ kind=$1 s=$2 g=$3; D=${WORKSPACE:-.}/3D_OrganoidSeg/baselines_fair_20261030/nnunet_ablation_$([ $kind = p512 ] && echo p512_20261112 || echo celoss_20261113); TR=$([ $kind = p512 ] && echo nnUNetTrainer || echo nnUNetTrainerCELoss); PL=$([ $kind = p512 ] && echo nnUNetPlans_p512 || echo nnUNetPlans)
  O=${WORKSPACE:-.}/3D_OrganoidSeg/baselines_fair_20261030/nnunet_ablations_eval_20261113/test_pred/${kind}_seed${s}_noTTA; [ -e $O ] && { echo "$O exists, skip"; return; }
  nnUNet_results=$D/nnUNet_results_${kind}_seed$s CUDA_VISIBLE_DEVICES=$g ${WORKSPACE:-.}/env_totalseg2/bin/nnUNetv2_predict -i ${WORKSPACE:-.}/3D_OrganoidSeg/baselines_fair_20261030/nnunet/nnUNet_raw/Dataset801_CRCOrganoid/imagesTs -o $O -d 801 -c 2d -f 0 -tr $TR -p $PL -chk checkpoint_final.pth --disable_tta > ${WORKSPACE:-.}/3D_OrganoidSeg/baselines_fair_20261030/nnunet_ablations_eval_20261113/logs/test_${kind}_${s}.full.log 2>&1
  ${PYTHON:-python} ${WORKSPACE:-.}/3D_OrganoidSeg/baselines_fair_20261030/eval_masks_shared.py --masks $O --out ${WORKSPACE:-.}/3D_OrganoidSeg/baselines_fair_20261030/nnunet_ablations_eval_20261113/shared_eval_test/${kind}_seed${s}_noTTA.json >> ${WORKSPACE:-.}/3D_OrganoidSeg/baselines_fair_20261030/nnunet_ablations_eval_20261113/logs/test_${kind}_${s}.full.log 2>&1
  echo "$kind $s rc=$? png=$(ls $O/*.png | wc -l)" >> ${WORKSPACE:-.}/3D_OrganoidSeg/baselines_fair_20261030/nnunet_ablations_eval_20261113/logs/run_test.log; }
(one p512 42 1; one p512 3407 1) & (one p512 2026 4; one celoss 42 4) & wait; echo ALL_TEST_DONE >> ${WORKSPACE:-.}/3D_OrganoidSeg/baselines_fair_20261030/nnunet_ablations_eval_20261113/logs/run_test.log
